class Cashier {
    int n,discount,counter=0;
    unordered_map<int,int> prices;
    public:Cashier(int n,int discount,vector<int>& products,vector<int>& values):n(n),discount(discount){
        for(int i=0;i<(int)products.size();++i)prices[products[i]]=values[i];
    }
    double getBill(vector<int> product,vector<int> amount){
        double total=0;
        for(int i=0;i<(int)product.size();++i)total+=prices[product[i]]*amount[i];
        ++counter;
        return counter%n==0?total*(100-discount)/100.0:total;
    }
};
